"""Build an honest single-file research case study from the saved records."""
import collections
import html
import json
from pathlib import Path

apps = json.loads(Path('assessed_dataset.json').read_text(encoding='utf-8'))
review = json.loads(Path('six_field_review.json').read_text(encoding='utf-8'))
old = {x['name']: x for x in json.loads(Path('final_dataset.json').read_text(encoding='utf-8'))}
for row in apps:
    row['purpose'] = old[row['name']].get('catalog_details', {}).get('purpose', '') or 'Purpose not yet verified'
assert len(apps) == len({x['name'] for x in apps}) == 100
assert len(review) == 60 and sum(r['rating'] == 'abstained' for r in review) == 60
listed = sum(x['fields']['composio_toolkit']['value'] == 'listed' for x in apps)
vendor_mcp = sum(x['fields']['official_mcp']['value'] == 'yes' for x in apps)
checked = sum(v['status'].startswith('reviewed') for x in apps for v in x['fields'].values())
unknown = sum(x['fields']['verdict']['value'] == 'unknown' for x in apps)
categories = collections.Counter(x['category'] for x in apps)
matrix = ''.join(f'<tr><th scope="row">{html.escape(k)}</th><td>{v}</td><td>0</td><td>{sum(a["category"]==k and a["fields"]["verdict"]["value"].startswith("needs approval") for a in apps)}</td><td>{sum(a["category"]==k and a["fields"]["verdict"]["value"]=="requires hosted wrapper for CLI" for a in apps)}</td><td>{sum(a["category"]==k and a["fields"]["verdict"]["value"]=="unknown" for a in apps)}</td></tr>' for k, v in categories.items())
payload = json.dumps(apps, ensure_ascii=False).replace('</', '<\\/')
reviews = json.dumps(review, ensure_ascii=False).replace('</', '<\\/')
page = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Integration evidence | Research in progress</title><style>
:root{--ink:#193a2f;--paper:#f3f2e9;--line:#cdd8ca;--lime:#d7f69a;--muted:#52685c}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.55 system-ui,sans-serif}a{color:#226443}header{background:#163d30;color:#f6f7ed;padding:26px max(5vw,24px) 80px}header a{color:#dcf3ca}.nav{display:flex;justify-content:space-between;font-size:12px;letter-spacing:.12em;text-transform:uppercase}.hero{max-width:1200px;margin:auto;display:grid;grid-template-columns:1.3fr .7fr;align-items:center;gap:30px}h1,h2{font-family:Georgia,serif;font-weight:400;line-height:1.08}h1{font-size:clamp(42px,6.6vw,80px);margin:76px 0 20px}h2{font-size:clamp(32px,4vw,48px);margin:0 0 18px}.lead{font-size:19px;max-width:730px;color:#d8e8da}.badge{display:inline-block;background:var(--lime);color:#1b3a2b;border-radius:40px;padding:6px 13px;font-size:12px;font-weight:700}.scene{border:1px solid #9abca4;border-radius:22px;padding:25px;display:grid;gap:16px}.step{border:1px solid #a9c7af;border-radius:10px;padding:13px}.step b{color:var(--lime);margin-right:12px}main{max-width:1200px;padding:0 24px;margin:auto}.metrics{display:grid;grid-template-columns:repeat(4,1fr);background:#fff;border:1px solid var(--line);margin-top:-35px}.metric{padding:26px;border-right:1px solid var(--line)}.metric strong{display:block;font:38px Georgia,serif}.metric small{color:var(--muted)}section{padding:70px 0;border-bottom:1px solid var(--line)}.kicker{font-size:12px;letter-spacing:.14em;text-transform:uppercase;font-weight:700;color:#51735a}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{background:white;border:1px solid var(--line);padding:25px}.card h3{margin-top:0}.notice{padding:22px;background:#e5edda;border-left:4px solid #6b9644}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;background:#fff;font-size:14px}th,td{padding:12px;border-bottom:1px solid #e0e7dd;text-align:left;vertical-align:top}thead th{font-size:12px;text-transform:uppercase}.controls{display:flex;flex-wrap:wrap;gap:12px;margin:22px 0}input,select,button{font:inherit;padding:10px;border:1px solid #a6b7a8;background:white;color:var(--ink)}button{cursor:pointer}input{min-width:210px}details{min-width:160px}summary{cursor:pointer;font-weight:650}.source{display:inline-block;margin-right:10px}.flow{display:flex;flex-wrap:wrap;gap:10px}.flow span{padding:13px;background:white;border:1px solid var(--line)}footer{padding:45px 0;color:var(--muted)}@media(max-width:760px){.hero{grid-template-columns:1fr}.scene{display:none}.metrics{grid-template-columns:repeat(2,1fr)}.metric{border-bottom:1px solid var(--line)}.cards{grid-template-columns:1fr}section{padding:50px 0}h1{margin-top:50px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}</style></head><body><header><nav class="nav"><span>Product ops / research case study</span><a href="#evidence">Explore evidence ↓</a></nav><div class="hero"><div><h1>100 apps. A decision needs more than a search result.</h1><p class="lead">A reproducible integration audit of the assigned list, with checked claims separated from unanswered questions. This edition is incomplete and is not ready to submit.</p><span class="badge">RESEARCH IN PROGRESS · NOT SUBMISSION READY</span></div><div class="scene" aria-label="Research workflow illustration"><div class="step"><b>01</b>Discover candidate sources</div><div class="step"><b>02</b>Check official evidence</div><div class="step"><b>03</b>Route a build decision</div></div></div></header><main><div class="metrics"><div class="metric"><strong>100</strong><small>assigned apps searched / 100</small></div><div class="metric"><strong>__LISTED__/100</strong><small>Composio catalog exact or alias matches</small></div><div class="metric"><strong>__UNKNOWN__/100</strong><small>buildability still unresolved</small></div><div class="metric"><strong>0/60</strong><small>baseline claims answered in review sample</small></div></div><section><div class="kicker">01 / Decisions first</div><h2>What can be decided today?</h2><div class="notice"><b>Google Ads has a documented production access gate; Sherlock and Mermaid CLI need execution environments for hosted use. __UNKNOWN__ of 100 verdicts remain unresolved.</b> A Composio listing is useful evidence of existing coverage, not a claim that its underlying vendor offers an MCP server or that production credentials are readily available.</div><div class="cards"><article class="card"><h3>Check existing coverage</h3><p>__LISTED__ of 100 app names map to a catalog listing: 61 exact names and 16 documented aliases. Review the scope of each match before building a duplicate.</p></article><article class="card"><h3>Investigate production access</h3><p>Google Ads documents test access and an application for production access. This is a concrete access question for product and engineering.</p><a href="https://developers.google.com/google-ads/api/docs/api-policy/access-levels">Google Ads access levels ↗</a></article><article class="card"><h3>Separate MCP ownership</h3><p>__MCP__ of 100 vendors have an official MCP server established in this limited review. The other records are unknown, not a count of vendors without one.</p></article></div></section><section><div class="kicker">02 / Category matrix</div><h2>Do not confuse unknown with blocked.</h2><p>One production-access gate and two CLI-wrapper judgments are supported so far. Counts show the evidence gap, not the actual market distribution.</p><div class="tablewrap"><table><thead><tr><th>Category</th><th>Apps</th><th>Build now</th><th>Gated</th><th>CLI wrapper</th><th>Unknown</th></tr></thead><tbody>__MATRIX__</tbody></table></div></section><section><div class="kicker">03 / Research agent</div><h2>Search, preserve, review.</h2><div class="flow"><span>100 first-pass searches</span><span>→ candidate retrieval</span><span>→ Composio catalog cross-check</span><span>→ independent AI-assisted review</span></div><p>The saved baseline deliberately abstained from all substantive answers. A second domain-restricted discovery pass saved candidate pages, and a separate script indexed possible claim passages for review. Neither candidate retrieval nor a keyword match establishes a claim. No applicant-performed manual review or live credential test is represented here.</p><p>Reproducible scripts, preserved records, and source text are in the project files. The exact app list is asserted to contain 100 unique names.</p></section><section><div class="kicker">04 / Accuracy lab</div><h2>Coverage is 0/60. Accuracy is undefined.</h2><p>The deliberately selected sample contains one app from each category and six fields per app: authentication, credential access, API surface, official MCP, Composio toolkit, and build verdict. The preserved first pass abstained on <b>60/60</b> claims; it answered <b>0/60</b>. Accuracy among answered claims is <b>0/0, undefined</b>. The review found at least partial evidence for __SAMPLE_RESOLVED__ of 60 fields; __SAMPLE_UNKNOWN__ remain unresolved. There is no before/after improvement claim and no random holdout experiment.</p><div class="cards"><article class="card"><h3>Slack: unknown → established</h3><p>Slack’s docs describe OAuth and an official MCP server. Composio’s catalog is checked separately.</p><a href="https://docs.slack.dev/ai/slack-mcp-server/">Vendor MCP documentation ↗</a></article><article class="card"><h3>Google Ads: unknown → access gate</h3><p>Test access is available after enabling the API; production access requires applying for an appropriate access level.</p><a href="https://developers.google.com/google-ads/api/docs/api-policy/access-levels">Access documentation ↗</a></article><article class="card"><h3>GitHub: unknown → API + MCP</h3><p>GitHub documents its REST API and its own MCP server. These are separate checked facts.</p><a href="https://github.com/github/github-mcp-server">Official MCP repository ↗</a></article></div><details><summary>Inspect all 60 sample comparisons</summary><div class="tablewrap"><table><thead><tr><th>App / claim</th><th>Baseline</th><th>Official evidence establishes</th><th>Source</th></tr></thead><tbody id="review"></tbody></table></div></details><p><small>“Unknown” in the checked column means the sources reviewed did not establish the claim; it does not mean the claim is false. Partial answers would receive half credit if a later experiment produced any.</small></p></section><section id="evidence"><div class="kicker">05 / The 100 apps</div><h2>Evidence, not assumptions.</h2><p>__CHECKED__ vendor-related claims or decisions have a specific independent documentation check. Catalog matches and unresolved fields are labeled independently. Expand each row to inspect fields and source links.</p><div class="controls"><label>Search <input id="search" type="search" placeholder="App or category"></label><label>Category <select id="category"><option value="">All categories</option></select></label><label>Catalog <select id="catalog"><option value="">All</option><option value="listed">Listed</option><option value="unknown">Unknown</option></select></label><button id="sort">Sort A–Z</button><button id="json">Export JSON</button><button id="csv">Export CSV</button></div><p id="count" aria-live="polite"></p><div class="tablewrap"><table><thead><tr><th>App</th><th>Category</th><th>Composio toolkit</th><th>Vendor MCP</th><th>Build verdict</th><th>Details</th></tr></thead><tbody id="rows"></tbody></table></div></section><section><div class="kicker">06 / Handoff and limitations</div><h2>Next: close the evidence gap.</h2><div class="cards"><article class="card"><h3>Engineering</h3><p>Review authentication and endpoint scope for each candidate; test representative connections with authorized credentials.</p></article><article class="card"><h3>Product</h3><p>Prioritize by customer demand and existing catalog coverage after resolving aliases and integration scope.</p></article><article class="card"><h3>Partner outreach</h3><p>Investigate unclear vendor access and production approval paths before committing to implementation dates.</p></article></div><p>The catalog snapshot and research were checked in November 2026. Most app fields, __UNKNOWN__ buildability verdicts, and a representative accuracy assessment remain unresolved. No live credentials were tested. The source repository and deployment are not yet verified.</p></section><footer>Composio assignment research · This page is an honest work in progress.</footer></main><script>
const data=__DATA__, review=__REVIEW__;const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const safe=u=>/^https?:\/\//i.test(u);let asc=true;[...new Set(data.map(a=>a.category))].forEach(c=>{let o=document.createElement('option');o.value=o.textContent=c;$('#category').append(o)});function sources(urls){return urls.filter(safe).map(u=>`<a class="source" href="${esc(u)}" target="_blank" rel="noopener">Source ↗</a>`).join(' ')}function render(){let q=$('#search').value.toLowerCase();let list=data.filter(a=>(a.name+' '+a.category).toLowerCase().includes(q)&&(!$('#category').value||a.category===$('#category').value)&&(!$('#catalog').value||a.fields.composio_toolkit.value===$('#catalog').value)).sort((a,b)=>asc?a.name.localeCompare(b.name):b.name.localeCompare(a.name));$('#count').textContent=`${list.length} of ${data.length} apps shown`;$('#rows').innerHTML=list.map(a=>`<tr><td><b>${esc(a.name)}</b></td><td>${esc(a.category)}</td><td>${esc(a.fields.composio_toolkit.value)}</td><td>${esc(a.fields.official_mcp.value)}</td><td>${esc(a.fields.verdict.value)}</td><td><details><summary>View evidence</summary><p>${esc(a.purpose)}</p>${a.composio_auth_config?`<p><b>Composio auth configuration:</b> ${esc(a.composio_auth_config.value)}. ${esc(a.composio_auth_config.note)} ${sources([a.composio_auth_config.source])}</p>`:''}${Object.entries(a.fields).map(([k,v])=>`<p><b>${esc(k.replaceAll('_',' '))}:</b> ${esc(v.value)} <em>(${esc(v.status)})</em> ${sources(v.sources)}</p>`).join('')}<p><b>Blocker:</b> ${esc(a.blocker)}</p><p><b>Next action:</b> ${esc(a.next_action)}</p></details></td></tr>`).join('')};$('#review').innerHTML=review.map(r=>`<tr><td>${esc(r.app)} / ${esc(r.field.replaceAll('_',' '))}</td><td>Abstained (${esc(r.original)})</td><td>${esc(r.documentation_establishes)}</td><td>${sources(r.sources)||'Unresolved'}</td></tr>`).join('');['search','category','catalog'].forEach(id=>$('#'+id).addEventListener('input',render));$('#sort').onclick=()=>{asc=!asc;$('#sort').textContent=asc?'Sort A–Z':'Sort Z–A';render()};function save(name,content,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}$('#json').onclick=()=>save('assessed-dataset.json',JSON.stringify(data,null,2),'application/json');$('#csv').onclick=()=>{let cols=['name','category','auth','credential_gate','api_surface','official_mcp','composio_toolkit','verdict'];let quote=x=>'"'+String(x??'').replaceAll('"','""')+'"';save('assessed-dataset.csv',[cols.join(','),...data.map(a=>cols.map(k=>quote(a[k]??a.fields[k]?.value)).join(','))].join('\r\n'),'text/csv')};render();</script></body></html>'''
for key, value in {'__LISTED__': listed, '__MCP__': vendor_mcp, '__UNKNOWN__': unknown, '__CHECKED__': checked, '__SAMPLE_RESOLVED__': sum(r['documentation_establishes'] != 'unknown' for r in review), '__SAMPLE_UNKNOWN__': sum(r['documentation_establishes'] == 'unknown' for r in review), '__MATRIX__': matrix, '__DATA__': payload, '__REVIEW__': reviews}.items():
    page = page.replace(key, str(value))
Path('index.html').write_text(page, encoding='utf-8')
print(f'Built page: {listed}/100 catalog matches, {vendor_mcp}/100 known vendor MCP, {checked} reviewed vendor claims, {unknown}/100 unknown verdicts')
